(() => {
  const all = Array.from(document.querySelectorAll('input')).map(i => ({id:i.id, type:i.type, name:i.name, ph:i.placeholder, autocomplete:i.autocomplete||''}));
  const btns = Array.from(document.querySelectorAll('button')).map(b => (b.innerText||'').trim()).filter(Boolean).slice(0,10);
  return JSON.stringify({inputs: all, buttons: btns, txt: (document.body.innerText||'').slice(0,300)});
})()
